void ScriptSession::faerieSpellInfo(SpellInfo& s){
    auto& data=definitions();auto field=[&](const char* key){return data.number(s.ability,"AbilityData",std::string(key)+std::to_string(s.level));};if(!s.buff || s.duration<=0 || s.duration>86400 || s.heroDuration<=0 || s.heroDuration>86400)throw std::runtime_error("Faerie ability requires source buff and durations");
    if(s.kind==SpellKind::PhaseShift){if(s.amount!=0 || s.secondary!=0)throw std::runtime_error("Nonzero Phase Shift behavior fields are not implemented");if(!s.orderOn)s.orderOn=orderId("phaseshifton");if(!s.orderOff)s.orderOff=orderId("phaseshiftoff");return;}
    s.unorder=orderId(data.field(s.ability,"Profile","Unorder"));s.channelled=true;s.channelTime=s.duration;s.period=0;s.animation="Morph";s.castDelay=field("Cast");s.maxDamage=field("DataD");s.armor=field("DataE");float casterOnly=field("DataF");s.manaFlareCasterOnly=casterOnly!=0;auto buffs=data.field(s.ability,"AbilityData","BuffID"+std::to_string(s.level));
    if(!s.unorder || s.area<=0 || s.range<0 || s.range>100000 || s.amount<0 || s.amount>99999 || s.secondary<0 || s.secondary>99999 || s.loss<0 || s.loss>1000000 || s.maxDamage<0 || s.maxDamage>1000000 || s.armor<0 || s.armor>99999 || s.castDelay<0 || s.castDelay>300 || (casterOnly!=0 && casterOnly!=1) || buffs.size()<9 || buffs[4]!=',')throw std::runtime_error("Mana Flare source limits, cast, armor or auxiliary buff outside supported range");s.guardBuff=ObjectData::code(buffs.substr(5,4));s.missile=data.field(s.guardBuff,"Profile","Missileart");s.speed=data.number(s.guardBuff,"Profile","Missilespeed");s.missileArc=data.number(s.guardBuff,"Profile","Missilearc");s.missileHoming=data.number(s.guardBuff,"Profile","MissileHoming",1)!=0;if(s.missile.empty() || s.missile=="_" || s.speed<=0 || s.speed>100000)throw std::runtime_error("Mana Flare requires its source reaction missile");
    for(auto buff:{s.buff,s.guardBuff})for(auto artField:{"Targetart","Specialart","Missileart"}){std::stringstream paths(data.field(buff,"Profile",artField));std::string model;while(std::getline(paths,model,','))if(!model.empty() && model!="_")s.visualModels.push_back(model);}
}
bool ScriptSession::phaseShift(std::uint32_t id,const SpellInfo& s,bool automatic){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);if(u->selfCasting || u->paused || u->hidden() || u->removing || u->abilitiesDisabled() || u->silenced() || u->construction || u->unsummon || u->illusion || number(u->life)<=0 || number(u->mana)<s.mana || spellCooldown(id,s.ability)>0 || !spellRequirements(u->owner,s))return false;auto available=config_.players[u->owner].abilityAvailable.find(s.ability);if(available!=config_.players[u->owner].abilityAvailable.end() && !available->second)return false;
    u->selfCasting=true;struct Reset {UnitState& unit;~Reset(){unit.selfCasting=false;}}reset{*u};auto death=u->deathRevision,ownership=u->ownerRevision;auto owner=u->owner;CastOrder cast;cast.caster=id;cast.owner=owner;cast.spell=s;cast.point={u->x,u->y};cast.abilityHandle=abilityHandle(id,s.ability);cast.started=true;
    auto valid=[&]{if(!alive(id,NativeKind::Unit) || u->removing || u->paused || u->hidden() || u->abilitiesDisabled() || u->silenced() || number(u->life)<=0 || u->deathRevision!=death || u->ownerRevision!=ownership || u->owner!=owner)return false;auto known=u->abilities.find(s.ability);auto enabled=config_.players[owner].abilityAvailable.find(s.ability);return known!=u->abilities.end() && known->second>0 && (enabled==config_.players[owner].abilityAvailable.end() || enabled->second);};
    if(!automatic){if(!cancelCombat(*u) || !valid())return false;u->route.clear();u->waypoint=0;u->holding=false;u->currentOrder=0;}else if(u->cast){if(!cancelCast(*u,true) || !valid())return false;u->currentOrder=0;}
    auto revision=u->castRevision,combat=u->combat.revision;auto unchanged=[&]{return valid() && u->castRevision==revision && u->combat.revision==combat;};ScriptContext context;context.issuedOrder=s.order;unitEvent(id,38,75,context);if(!unchanged())return true;for(unsigned stage=0;stage<2;++stage){spellEvent(id,cast,stage);if(!unchanged())return true;}if(number(u->mana)<s.mana || spellCooldown(id,s.ability)>0 || !spellRequirements(owner,s))return true;
    u->mana=real(number(u->mana)-s.mana);u->spellCooldowns[s.ability]=simulationTime_+s.cooldown;bookSharedCooldown(*u,s.ability,s.cooldown);breakInvisibility(*u);spellEvent(id,cast,2);if(!unchanged())return true;UnitBuff buff;buff.id=s.buff;buff.source=buff.target=id;buff.ability=buff.originAbility=s.ability;buff.sourceLevel=s.level;buff.sourceOwner=owner;buff.kind=BuffKind::PhaseShift;buff.remaining=u->hero?s.heroDuration:s.duration;buff.positive=buff.physical=true;buff.dispellable=false;if(auto old=u->buffs.find(s.buff);old!=u->buffs.end()){releaseBuff(old->second);u->buffs.erase(old);}u->buffs[s.buff]=std::move(buff);++fogRevision_;for(auto visual:spellVisual(s,"Specialart",0,{u->x,u->y}))effects_.at(visual)->z=u->displayFlyHeight();
    spellEvent(id,cast,3);if(alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->deathRevision==death && u->ownerRevision==ownership)spellEvent(id,cast,4);return true;
}
bool ScriptSession::phaseShiftReaction(std::uint32_t id,std::uint32_t attacker){
    if(!alive(id,NativeKind::Unit) || !alive(attacker,NativeKind::Unit))return false;auto u=units_.at(id),source=units_.at(attacker);if(!enemy(source->owner,u->owner) || source->removing || number(source->life)<=0 || u->hidden() || u->paused || u->removing || u->abilitiesDisabled() || u->silenced() || u->illusion || u->selfCasting || number(u->life)<=0)return false;
    for(auto [ability,enabled]:u->autocast){if(!enabled)continue;auto known=u->abilities.find(ability);if(known==u->abilities.end() || known->second<=0)continue;auto& s=spellInfo(ability,unsigned(known->second));if(s.kind==SpellKind::PhaseShift && phaseShift(id,s,true))return u->phaseShifted();}return false;
}
bool ScriptSession::manaFlareActive(const UnitState& u,const SpellInfo& s) const{return s.kind==SpellKind::ManaFlare && u.cast && u.cast->spell.ability==s.ability && u.cast->phase==CastOrder::Phase::Channel;}
bool ScriptSession::stopManaFlare(std::uint32_t id,std::uint32_t ability){
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);if(u->paused || u->hidden() || u->removing || number(u->life)<=0 || !u->cast || u->cast->spell.kind!=SpellKind::ManaFlare || u->cast->spell.ability!=ability)return false;auto order=u->cast->spell.unorder;if(!cancelCast(*u))return true;ScriptContext context;context.issuedOrder=order;unitEvent(id,38,75,context);return true;
}
void ScriptSession::startManaFlare(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!u->cast || u->cast->ticket!=cast.ticket)return;startChannel(id);if(!u->cast || u->cast->ticket!=cast.ticket)return;auto& s=cast.spell;UnitBuff buff;buff.id=s.buff;buff.source=buff.target=id;buff.ability=buff.originAbility=s.ability;buff.sourceLevel=s.level;buff.sourceOwner=cast.owner;buff.applied=cast.ticket;buff.kind=BuffKind::ManaFlare;buff.positive=buff.physical=buff.persistent=true;buff.dispellable=false;buff.armor=s.armor;auto art=s;art.ability=s.buff;buff.visuals=spellVisual(art,"Targetart",id,{u->x,u->y},false);if(auto old=u->buffs.find(s.buff);old!=u->buffs.end()){releaseBuff(old->second);u->buffs.erase(old);}u->buffs[s.buff]=std::move(buff);u->animation="Stand Alternate";u->animationTime=0;manaFlareActors_.insert(id);
}
void ScriptSession::releaseManaFlare(const CastOrder& cast){
    if(cast.spell.kind!=SpellKind::ManaFlare)return;manaFlareActors_.erase(cast.caster);if(!alive(cast.caster,NativeKind::Unit))return;auto u=units_.at(cast.caster);auto found=u->buffs.find(cast.spell.buff);if(found!=u->buffs.end() && found->second.kind==BuffKind::ManaFlare && found->second.applied==cast.ticket){releaseBuff(found->second);u->buffs.erase(found);}
}
void ScriptSession::manaFlareReaction(std::uint32_t caster,const CastOrder& paid){
    if(paid.item || paid.spell.mana<=0 || manaFlareActors_.empty() || !alive(caster,NativeKind::Unit))return;auto target=units_.at(caster);if(target->removing || target->hidden() || number(target->life)<=0 || target->owner!=paid.owner)return;std::vector<std::uint32_t> actors(manaFlareActors_.begin(),manaFlareActors_.end());
    for(auto id:actors){if(!alive(caster,NativeKind::Unit) || target->removing || target->hidden() || number(target->life)<=0 || target->owner!=paid.owner)break;if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!u->cast || u->cast->spell.kind!=SpellKind::ManaFlare || u->cast->phase!=CastOrder::Phase::Channel || u->paused || u->stunned() || u->silenced() || u->hidden() || u->removing || number(u->life)<=0 || u->owner!=u->cast->owner)continue;auto cast=*u->cast;auto& s=cast.spell;auto mark=u->buffs.find(s.buff);if(mark==u->buffs.end() || mark->second.kind!=BuffKind::ManaFlare || mark->second.applied!=cast.ticket || !spellTarget(*u,*target,s,true,cast.owner) || std::hypot(number(u->x)-number(target->x),number(u->y)-number(target->y))>s.area+target->collision)continue;
        SpellMissile missile;missile.spell=s;missile.source=id;missile.target=caster;missile.owner=cast.owner;missile.sourceDeath=u->deathRevision;missile.targetDeath=target->deathRevision;missile.position={u->x,u->y};missile.mana=paid.spell.mana;auto graphic=missile;graphic.spell.ability=s.buff;spellLightning(graphic);launchSpellMissile(std::move(missile));
    }
}
bool ScriptSession::manaFlareImpact(const SpellMissile& missile){
    auto& s=missile.spell;if(s.kind!=SpellKind::ManaFlare)return false;if(!alive(missile.target,NativeKind::Unit))return true;auto primary=units_.at(missile.target);if(primary->deathRevision!=missile.targetDeath || primary->removing || primary->hidden() || number(primary->life)<=0)return true;UnitState source;source.handle=missile.source;source.owner=missile.owner;WorldPoint point{primary->x,primary->y};std::vector<std::pair<std::uint32_t,std::uint64_t>> targets;
    if(s.manaFlareCasterOnly){if(spellTarget(source,*primary,s,false,missile.owner))targets.emplace_back(missile.target,primary->deathRevision);}else for(auto& [id,u]:units_)if(std::hypot(number(u->x)-number(point.x),number(u->y)-number(point.y))<=s.range+u->collision && spellTarget(source,*u,s,false,missile.owner))targets.emplace_back(id,u->deathRevision);
    auto art=s;art.ability=s.guardBuff;for(auto visual:spellVisual(art,"Specialart",0,point))effects_.at(visual)->z=primary->displayFlyHeight();for(auto [id,death]:targets){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(u->deathRevision!=death || !spellTarget(source,*u,s,false,missile.owner))continue;float amount=std::min(missile.mana*(u->hero?s.secondary:s.amount),u->hero?s.maxDamage:s.loss);auto from=alive(missile.source,NativeKind::Unit)?units_.at(missile.source):nullptr;auto sourceId=from && !from->removing && from->deathRevision==missile.sourceDeath && from->owner==missile.owner?missile.source:0;damageUnit(sourceId,id,amount,0,14,false,false,nullptr,false,true,missile.owner);if(alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->deathRevision==death)spellVisual(art,"Targetart",id,{u->x,u->y});}return true;
}
